#include<bits/stdc++.h>
using namespace std;using U=uint64_t;struct Op{U k,v,f,c,r;int g;bool operator<(Op const&o)const{return tie(k,v,f,c,r,g)<tie(o.k,o.v,o.f,o.c,o.r,o.g);}};struct E{int fr,to,op,a;};struct VH{size_t operator()(vector<pair<int,int>>const&v)const{size_t h=0;for(auto[a,b]:v){h^=(uint64_t(a+1)*0x9e3779b97f4a7c15ULL+uint64_t(b+2)*0xbf58476d1ce4e5b9ULL)+(h<<6)+(h>>2);}return h;}};
int main(int ac,char**av){ifstream in(av[1]);int n,np,nt,nr,sp;U sk,sv;in>>n>>np>>nt>>nr>>sp>>sk>>sv;assert(nr==0);vector<E>edges;vector<vector<int>>adj(np);vector<Op>ops;map<Op,int>opids;for(int i=0;i<nt;i++){int fr,to,g,a;U k,v,f,c,r;in>>fr>>to>>k>>v>>f>>c>>r>>g>>a;if(g)f=c=r=0;Op op{k,v,f,c,r,g};auto it=opids.find(op);int id;if(it==opids.end()){id=ops.size();ops.push_back(op);opids[op]=id;}else id=it->second;adj[fr].push_back(edges.size());edges.push_back({fr,to,id,a});}assert(in);vector<int>part(np,0);int rounds=0,nc=1;for(;;){unordered_map<vector<pair<int,int>>,int,VH>mp;vector<int>next(np);for(int s=0;s<np;s++){vector<pair<int,int>>sig;for(int ei:adj[s]){auto&e=edges[ei];sig.push_back({e.op,ops[e.op].g?-1:part[e.to]});}sort(sig.begin(),sig.end());sig.erase(unique(sig.begin(),sig.end()),sig.end());auto[it,ok]=mp.emplace(sig,mp.size());next[s]=it->second;}rounds++;nc=mp.size();cerr<<"round "<<rounds<<" classes "<<nc<<"\n";if(next==part)break;part.swap(next);}vector<int>rep(nc,-1);for(int s=0;s<np;s++)if(rep[part[s]]<0)rep[part[s]]=s;vector<array<U,9>>T;for(int cl=0;cl<nc;cl++){set<pair<int,int>>seen;for(int ei:adj[rep[cl]]){auto&e=edges[ei];auto&o=ops[e.op];int dest=o.g?nc:part[e.to];if(seen.insert({e.op,dest}).second)T.push_back({U(cl),U(dest),o.k,o.v,o.f,o.c,o.r,U(o.g),U(e.a)});}}ofstream out(av[2]);out<<n<<" "<<nc+1<<" "<<T.size()<<" 0\n"<<part[sp]<<" "<<sk<<" "<<sv<<"\n";for(auto&t:T){for(int j=0;j<9;j++)out<<(j?" ":"")<<t[j];out<<"\n";}out<<"\n";ofstream m(av[3]);m<<np<<" "<<nc<<" "<<rounds<<"\n";for(int x:part)m<<x<<" ";m<<"\n";cout<<"old_positions "<<np<<" new_positions "<<nc+1<<" old_edges "<<nt<<" new_edges "<<T.size()<<" rounds "<<rounds<<"\n";}
